EL['v-altri']={f:[['nome','Azienda','t'],['regione','Regione','s',['Basilicata','Puglia']],['settore','Settore','t'],['citta','Sede','t'],['sito','Sito web','t'],['referente','Referente commerciale','t'],['telefono','Telefono aziendale','t'],['email','Email aziendale','t'],['fonte','Da dove viene il dato','t'],['contattato','Contattata?','s',['No','Sì']],['esito','Esito','s',STATI_SP],['responsabile','Chi la segue','t'],['prossima','Prossima azione','t'],['nota','Note','ta']],intro:'Aziende di Basilicata e Puglia da proporre come sponsor. Usa solo dati aziendali pubblici o forniti dalle aziende, e rispetta le regole sulla privacy e sulle comunicazioni promozionali.',add:'Aggiungi un’azienda',group:'regione'};
EL['v-area']={f:[['spazio','Spazio','s',['Banner','Programma','Striscioni','Ledwall','Diretta','Social','Comunicazione','Altro']],['descr','Descrizione','t'],['formato','Formato','t'],['visibilita','Visibilità (dove, quanto)','t'],['prezzo','Valore (€)','n'],['condizioni','Condizioni','t'],['stato','Stato','s',['Libero','In trattativa','Opzionato','Venduto']],['interessati','Sponsor interessati','t'],['a','Venduto a','t']],intro:'Gli spazi in vendita: banner, programma, striscioni, ledwall, diretta, social, comunicazione.',add:'Aggiungi uno spazio',group:'spazio'};
delete EL['v-prot'];
