EL['v-voci'].f=[['nome','Voce o attività','t'],['anno','Anno','s',['2026','2027']],['costo','Costi diretti (€)','n'],['indiretti','Costi indiretti attribuiti (€)','n'],['ricavo','Ricavi diretti (€)','n'],['verifica','Questi numeri sono…','s',['Una stima','Verificati con documenti']],['nota','Nota','ta'],['doc','Documento di supporto','f']];
