function storicoRec(d){const S2=d.storico||[];if(!S2.length)return null;return h('<details class="storico2"><summary>Storico · '+S2.length+'</summary>'+S2.slice().reverse().map(x=>'<div class="sti"><b>'+esc(nome(x.chi))+'</b> · '+new Date(x.quando).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+'<br>'+x.cambi.map(c=>esc(c[0])+': '+esc(String(c[1]||'—'))+' → '+esc(String(c[2]||'—'))).join('<br>')+'</div>').join('')+'</details>');}

/* --- Analisi economica delle attività --- */
function renderAttivita(){const id='v-voci',el=document.getElementById(id);el.innerHTML='';addBack(id);const L1=VD[id]||[],can=CTX.canEdit(id);const yr=elFilt[id]||'2026';
  el.appendChild(h('<div class="sh"><span class="eyb">Economia</span><h2>Costi e guadagni per attività</h2><p>Per ogni voce o attività: costi diretti, costi indiretti attribuiti, ricavi, risultato e margine. Le stime sono segnate in modo diverso dai numeri verificati con documenti.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button></div></div>'));
  const seg=h('<div class="seg">'+['2026','2027'].map(y=>'<button type="button" aria-pressed="'+(y===yr)+'">'+y+'</button>').join('')+'</div>');seg.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{elFilt[id]=b.textContent;renderAttivita();}));el.appendChild(seg);
  const LL=L1.filter(r=>(r.dati.anno||'2026')===yr);const n=x=>+x||0;const co=LL.reduce((a,r)=>a+n(r.dati.costo)+n(r.dati.indiretti),0),ri=LL.reduce((a,r)=>a+n(r.dati.ricavo),0);const ver=LL.filter(r=>r.dati.verifica==='Verificati con documenti').length;
  el.appendChild(h('<div class="big3"><div class="kpi"><span>Costi totali</span><b>'+eur(co)+'</b></div><div class="kpi"><span>Ricavi</span><b>'+eur(ri)+'</b></div><div class="kpi dark"><span>Risultato</span><b class="'+(ri-co>=0?'pos':'neg')+'">'+(ri-co>=0?'+':'−')+eur(Math.abs(ri-co))+'</b></div></div>'));
  if(LL.length)el.appendChild(h('<p class="muted small">'+ver+' su '+LL.length+' voci verificate con documenti. Le altre sono stime.</p>'));
  if(can&&CTX.eco&&!L1.length)el.appendChild(addBtn('Riempi con le 7 aree del bilancio 2026',async()=>{await CTX.sb.from('voci_dati').insert(D.bil.map(a=>({voce:id,dati:{nome:a.n,anno:'2026',costo:Math.round(a.t),indiretti:'',ricavo:'',verifica:'Verificati con documenti',nota:'Dal bilancio 2026'}})));await loadVD();renderAttivita();}));
  if(can)el.appendChild(addBtn('+ Aggiungi una voce o un’attività',()=>editRec(id,null,{anno:yr,verifica:'Una stima'})));
  const g=h('<div class="cgrid"></div>');
  LL.forEach(r=>{const d=r.dati,c1=n(d.costo),c2=n(d.indiretti),rc=n(d.ricavo),tot=c1+c2,ris=rc-tot,mg=rc?Math.round(ris/rc*100):null,mx=Math.max(tot,rc,1);const stima=d.verifica!=='Verificati con documenti';
    const c=h('<article class="card vc"><div class="chips"><span class="chip2 '+(stima?'':'ok')+'">'+(stima?'Stima':'Verificato')+'</span>'+(stima&&!d.doc?'<span class="chip2 ko">Senza documenti</span>':'')+'</div><b class="vn">'+esc(d.nome||'Senza nome')+'</b><div class="bar2"><div><span>Costi'+(c2?' (di cui indiretti '+eur(c2)+')':'')+'</span><b>'+(d.costo!==''&&d.costo!=null?eur(tot):'da inserire')+'</b></div><i><i style="width:'+(tot/mx*100)+'%;background:#9A9CA6"></i></i><div><span>Ricavi</span><b>'+(d.ricavo!==''&&d.ricavo!=null?eur(rc):'da inserire')+'</b></div><i><i style="width:'+(rc/mx*100)+'%;background:var(--acc)"></i></i></div><div class="res '+(ris>=0?'pos':'neg')+'">Risultato: <b>'+(ris>=0?'+':'−')+eur(Math.abs(ris))+'</b>'+(mg!=null?' · margine '+mg+'%':'')+'</div>'+(d.nota?'<p class="muted small">'+esc(d.nota)+'</p>':'')+'</article>');
    if(d.doc&&d.doc.path)c.appendChild(fileBtn(d.doc,'Documento di supporto'));const sto=storicoRec(d);if(sto)c.appendChild(sto);if(can)c.appendChild(rowBtns(id,r));g.appendChild(c);});
  el.appendChild(g);if(!LL.length)el.appendChild(h('<div class="card soon"><p>Nessuna voce per il '+yr+'.</p></div>'));}

/* --- Carità: movimenti, beneficiari riservati, saldo --- */
function renderCarita(){const id='v-care',el=document.getElementById(id);el.innerHTML='';addBack(id);const L1=VD[id]||[],can=CTX.canEdit(id);const n=x=>+x||0;
  el.appendChild(h('<div class="sh"><span class="eyb">Economia</span><h2>Erogazioni della carità</h2><p>Entrate del fondo (compresa la quota annuale dell’Associazione) ed erogazioni, con i documenti. I beneficiari segnati come riservati restano nascosti a chi può solo guardare.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button></div></div>'));
  const ent=L1.filter(r=>r.dati.tipo!=='Erogazione'),ero=L1.filter(r=>r.dati.tipo==='Erogazione');const E1=ent.reduce((a,r)=>a+n(r.dati.importo),0),E2=ero.reduce((a,r)=>a+n(r.dati.importo),0);
  el.appendChild(h('<div class="big3"><div class="kpi"><span>Entrate del fondo</span><b>'+eur(E1)+'</b></div><div class="kpi"><span>Erogato</span><b>'+eur(E2)+'</b></div><div class="kpi dark"><span>Saldo</span><b class="'+(E1-E2>=0?'pos':'neg')+'">'+eur(E1-E2)+'</b></div></div>'));
  if(canV('s-car'))el.appendChild(h('<p class="muted small">Le ipotesi sul fondo (quota alla Curia, fondo dei fornitori) sono nella scheda <button type="button" class="lnk2" data-go="s-car">Carità</button>.</p>'));
  if(can)el.appendChild(addBtn('+ Registra un movimento',()=>editRec(id,null,{tipo:'Erogazione',riservato:'No'})));
  const g=h('<div class="cgrid"></div>');L1.slice().sort((a,b)=>String(b.dati.data||'').localeCompare(String(a.dati.data||''))).forEach(r=>{const d=r.dati;const nasc=d.riservato==='Sì'&&!can;
    const c=h('<article class="card rc"><div class="chips"><span class="chip2 '+(d.tipo==='Erogazione'?'':'ok')+'">'+esc(d.tipo||'')+'</span>'+(d.riservato==='Sì'?'<span class="chip2">Riservato</span>':'')+'</div><b class="vn">'+(nasc?'Beneficiario riservato':esc(d.beneficiario||''))+'</b><b class="amt">'+eur(n(d.importo))+'</b>'+(d.data?'<div class="fact2"><span>Data</span><b>'+fmtD(d.data)+'</b></div>':'')+(d.nota&&!nasc?'<p class="muted small">'+esc(d.nota)+'</p>':'')+'</article>');
    if(d.doc&&d.doc.path&&!nasc)c.appendChild(fileBtn(d.doc,'Documento'));if(can)c.appendChild(rowBtns(id,r));g.appendChild(c);});el.appendChild(g);
  if(!L1.length)el.appendChild(h('<div class="card soon"><p>Nessun movimento registrato.</p></div>'));}

/* --- Schede delle voci 2027: previsto, effettivo, fornitore, preventivi, contratto, fatture, pagamenti, documenti --- */
let CVSEL=null;
function renderSchede(){const id='v-cv',el=document.getElementById(id);el.innerHTML='';addBack(id);const can=CTX.canEdit(id);
  if(!CTX.eco||!(D.prev||[]).length){el.appendChild(h('<div class="card soon"><p>Per vedere le schede servono i dati del bilancio (sezione Economia).</p></div>'));return;}
  const REC={};(VD[id]||[]).forEach(r=>REC[r.dati.vid]=r);const prev=VD['v-prev']||[],for27=VD['v-for27']||[],fatt=VD['v-fatt']||[];
  const info=v=>{const P2=prev.filter(x=>x.dati.voce===v.n),F=for27.filter(x=>x.dati.voce===v.n),FT=fatt.filter(x=>x.dati.voce===v.n&&x.dati.tipo!=='Ricavo');const r=REC[v.id];
    const previsto=voceOn(v)?voceV(v):0;const eff=r&&r.dati.effettivo!==''&&r.dati.effettivo!=null?+r.dati.effettivo:(FT.length?FT.reduce((a,x)=>a+(+x.dati.importo||0),0):null);
    const pag=F.flatMap(x=>x.dati.pagamenti||[]);return {P2,F,FT,r,previsto,eff,pag};};
  if(CVSEL){const v=Object.values(VOCI).find(x=>x.id===CVSEL);if(v)return schedaVoce(el,v,info(v),can);}
  el.appendChild(h('<div class="sh"><span class="eyb">Economia</span><h2>Schede delle voci 2027</h2><p>Ogni voce della previsione 2027 con previsto ed effettivo, fornitore, preventivi, contratto, fatture, pagamenti e documenti. L’effettivo si calcola dalle fatture collegate, oppure lo scrivi tu.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button></div></div>'));
  let tp=0,te=0,tpe=0,ne=0;D.prev.forEach(a=>a.voci.forEach(v=>{const x=info(v);tp+=x.previsto;if(x.eff!=null){te+=x.eff;tpe+=x.previsto;ne++;}}));const sc=te-tpe;
  el.appendChild(h('<div class="big3"><div class="kpi"><span>Previsto 2027</span><b>'+eur(tp)+'</b></div><div class="kpi"><span>Effettivo finora</span><b>'+eur(te)+'</b></div><div class="kpi dark"><span>Scostamento'+(ne?' su '+ne+(ne===1?' voce':' voci'):'')+'</span><b class="'+(!ne?'':sc<=0?'pos':'neg')+'">'+(!ne?'—':(sc>=0?'+':'−')+eur(Math.abs(sc)))+'</b></div></div>'));
  D.prev.forEach(a=>{const sec=h('<details class="area cv"><summary><div class="sumrow"><span class="t">'+esc(a.n)+'</span></div></summary><div class="rows"></div></details>');
    a.voci.forEach(v=>{const x=info(v);const row=h('<button type="button" class="cvrow"><span class="n">'+esc(v.n)+(voceOn(v)?'':' <span class="chip2">esclusa</span>')+'</span><span class="cvn"><b>'+eur(x.previsto)+'</b><em>'+(x.eff!=null?'effettivo '+eur(x.eff):'effettivo da inserire')+'</em></span><span class="cvi">'+(x.F.length?'fornitore ✓':'')+(x.P2.length?' · '+x.P2.length+' prev.':'')+(x.FT.length?' · '+x.FT.length+' fatt.':'')+'</span></button>');
      row.addEventListener('click',()=>{CVSEL=v.id;renderSchede();window.scrollTo({top:0});});sec.querySelector('.rows').appendChild(row);});el.appendChild(sec);});}
function schedaVoce(el,v,x,can){const id='v-cv';const d=x.r?x.r.dati:{vid:v.id,effettivo:'',descr:'',note:'',files:[]};
  const b=h('<button type="button" class="back">‹ Tutte le voci</button>');b.addEventListener('click',()=>{CVSEL=null;renderSchede();});el.appendChild(b);
  const scost=x.eff!=null?x.eff-x.previsto:null;
  el.appendChild(h('<div class="sh"><span class="eyb">Scheda della voce</span><h2>'+esc(v.n)+'</h2></div>'));
  el.appendChild(h('<div class="big3"><div class="kpi"><span>Previsto 2027</span><b>'+eur(x.previsto)+'</b></div><div class="kpi"><span>Effettivo</span><b>'+(x.eff!=null?eur(x.eff):'—')+'</b></div><div class="kpi dark"><span>Scostamento</span><b class="'+(scost==null?'':scost<=0?'pos':'neg')+'">'+(scost==null?'—':(scost>=0?'+':'−')+eur(Math.abs(scost)))+'</b></div></div>'));
  const cardF=h('<section class="card"><h3>Fornitore, contratto e pagamenti</h3>'+(x.F.length?x.F.map(f=>'<div class="fact2"><span>Fornitore</span><b>'+esc(f.dati.fornitore)+' · '+eur(+f.dati.importo||0)+'</b></div><div class="fact2"><span>Contratto</span><b>'+(f.dati.contratto?'allegato':'da allegare')+'</b></div>'+(f.dati.pagamenti||[]).map(p=>'<div class="fact2"><span>'+esc(p.n||'Pagamento')+(p.data?' · '+fmtD(p.data):'')+'</span><b>'+eur(+p.importo||0)+' · '+statoRata(p)[0].toLowerCase()+'</b></div>').join('')).join(''):'<p class="muted">Nessun fornitore scelto per questa voce.</p>')+(canV('v-for27')?'<button type="button" class="lnk2" data-go="v-for27">Apri Fornitori 2027</button>':'')+'</section>');el.appendChild(cardF);
  el.appendChild(h('<section class="card"><h3>Preventivi</h3>'+(x.P2.length?x.P2.map(p=>'<div class="rq"><div><b>'+esc(p.dati.fornitore||'da trovare')+'</b><span>'+esc(p.dati.stato||'')+'</span></div><b>'+(+p.dati.importo?eur(+p.dati.importo):'')+'</b></div>').join(''):'<p class="muted">Nessun preventivo.</p>')+(canV('v-prev')?'<button type="button" class="lnk2" data-go="v-prev">Apri i Preventivi</button>':'')+'</section>'));
  el.appendChild(h('<section class="card"><h3>Fatture collegate</h3>'+(x.FT.length?x.FT.map(f=>'<div class="rq"><div><b>'+esc(f.dati.soggetto||'')+'</b><span>'+(f.dati.data?fmtD(f.dati.data):'')+(f.dati.numero?' · n. '+esc(f.dati.numero):'')+' · '+(f.dati.pagata==='Sì'?'pagata':'da pagare')+'</span></div><b>'+eur(+f.dati.importo||0)+'</b></div>').join(''):'<p class="muted">Nessuna fattura collegata: nelle Fatture scegli questa voce.</p>')+'</section>'));
  const cd=h('<section class="card"><h3>Descrizione, effettivo e documenti</h3><div class="ctl"><label for="cv_d">Descrizione</label><textarea id="cv_d">'+esc(d.descr||v.nota||'')+'</textarea></div><div class="ctl"><label for="cv_e">Importo effettivo (€) — vuoto = somma delle fatture</label><input type="number" id="cv_e" step="any" inputmode="decimal" value="'+esc(d.effettivo)+'"></div><div class="ctl"><label for="cv_n">Note</label><textarea id="cv_n">'+esc(d.note||'')+'</textarea></div><div class="lab">Documenti</div><div class="cvf"></div>'+(can?'<label class="bb soft sm upl">Allega un documento<input type="file" hidden></label><div class="big-btns"><button type="button" class="bb dark" id="cv_s">Salva</button></div>':'')+'</section>');
  (d.files||[]).forEach(f=>cd.querySelector('.cvf').appendChild(fileBtn(f)));if(!(d.files||[]).length)cd.querySelector('.cvf').appendChild(h('<p class="muted small">Nessun documento.</p>'));
  if(!can)cd.querySelectorAll('textarea,input').forEach(i=>i.disabled=true);
  const salva=async(extra)=>{const o=Object.assign({},d,{descr:cd.querySelector('#cv_d').value.trim(),effettivo:cd.querySelector('#cv_e').value===''?'':+cd.querySelector('#cv_e').value,note:cd.querySelector('#cv_n').value.trim()},extra||{});
    const cambi=[['Descrizione',d.descr||'',o.descr],['Effettivo',d.effettivo,o.effettivo],['Note',d.note||'',o.note]].filter(c=>String(c[1])!==String(c[2]));if(extra&&extra.files)cambi.push(['Documenti',(d.files||[]).length,o.files.length]);
    if(cambi.length)o.storico=(d.storico||[]).concat([{quando:new Date().toISOString(),chi:CTX.user.id,cambi}]).slice(-30);
    const q=x.r?CTX.sb.from('voci_dati').update({dati:o,aggiornato:new Date().toISOString()}).eq('id',x.r.id):CTX.sb.from('voci_dati').insert({voce:id,dati:o});const {error}=await q;if(error){stEl.textContent='Non salvato: '+error.message;return;}await loadVD();renderSchede();stEl.textContent='Salvato.';};
  if(can){cd.querySelector('#cv_s').addEventListener('click',()=>salva());cd.querySelector('.upl input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;stEl.textContent='Carico…';try{const k=await carica(f,id);await salva({files:(d.files||[]).concat([k])});}catch(err){stEl.textContent=err.message;}});}
  el.appendChild(cd);const sto=storicoRec(d);if(sto)el.appendChild(sto);}

/* --- Richieste del Presidente: priorità, area, allegato, stati --- */
const STR={aperta:['Da prendere','ko'],presa:['Presa in carico',''],lavorazione:['In lavorazione',''],attesa:['In attesa',''],fatta:['Completata','ok']};
function areaSelect(id,val){return '<select id="'+id+'"><option value="">Nessuna in particolare</option>'+SEZ.map(s=>'<optgroup label="'+esc(s.n)+'">'+s.v.map(v=>'<option value="'+v[0]+'"'+(v[0]===val?' selected':'')+'>'+esc(s.n+' › '+v[1])+'</option>').join('')+'</optgroup>').join('')+'</select>';}
function renderReq2(){const el=document.getElementById('p-req');el.innerHTML='';const me=CTX.user.id,today=todayISO();
  el.appendChild(h('<div class="sh"><span class="eyb">Per tutti</span><h2>Richieste del Presidente</h2><p>Le vedono tutti. Chi ne prende una scrive entro quando la consegna, poi aggiorna lo stato fino al completamento.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button></div></div>'));
  if(isPres())el.appendChild(addBtn('+ Nuova richiesta',()=>{const d=sheet('Nuova richiesta','<div class="ctl"><label for="rq_t">Oggetto</label><input type="text" id="rq_t"></div><div class="ctl"><label for="rq_x">Descrizione</label><textarea id="rq_x"></textarea></div><div class="when"><div class="ctl"><label for="rq_p">Priorità</label><select id="rq_p">'+PRIORITA.map(p=>'<option>'+p+'</option>').join('')+'</select></div><div class="ctl"><label for="rq_a">Area interessata</label>'+areaSelect('rq_a','')+'</div></div><div class="ctl"><label for="rq_f">Documento allegato (facoltativo)</label><input type="file" id="rq_f"></div>','Invia a tutti',async(dl)=>{
      const t=dl.querySelector('#rq_t').value.trim();if(!t){dl.querySelector('.smsg').textContent='Scrivi l’oggetto.';return false;}const f=dl.querySelector('#rq_f').files[0];const al=f?await carica(f,'richieste/'+me):null;
      const {data:nr,error}=await CTX.sb.from('richieste').insert({titolo:t,testo:dl.querySelector('#rq_x').value.trim()||null,priorita:dl.querySelector('#rq_p').value,area:dl.querySelector('#rq_a').value||null,allegato:al}).select().single();if(error)throw new Error(error.message);if(nr)aiConsigli(nr.id);await loadSocial();renderReq2();stEl.textContent='Richiesta inviata a tutti.';});}));
  const late=r=>['presa','lavorazione','attesa'].includes(r.stato)&&r.entro&&r.entro<today;
  const grp=[['Da prendere',r=>r.stato==='aperta'],['In ritardo',late],['In corso',r=>['presa','lavorazione','attesa'].includes(r.stato)&&!late(r)],['Completate',r=>r.stato==='fatta']];
  const pr=r=>({Urgente:0,Alta:1,Normale:2,Bassa:3}[r.priorita||'Normale']);
  grp.forEach(([lab,f])=>{const L1=RICH.filter(f).sort((a,b)=>pr(a)-pr(b));if(!L1.length)return;el.appendChild(h('<h3 class="gh">'+lab+' · '+L1.length+'</h3>'));const g=h('<div class="cgrid"></div>');
    L1.forEach(r=>{const st=STR[r.stato]||STR.aperta;const v=r.area&&VOCE[r.area];
      const c=h('<article class="card rc'+(r.stato==='aperta'?' hot':'')+'"><div class="chips"><span class="chip2 '+st[1]+'">'+st[0]+'</span>'+(late(r)?'<span class="chip2 ko">In ritardo</span>':'')+(r.priorita&&r.priorita!=='Normale'?'<span class="chip2 '+(r.priorita==='Urgente'||r.priorita==='Alta'?'ko':'')+'">Priorità '+esc(r.priorita.toLowerCase())+'</span>':'')+'</div><b class="vn">'+esc(r.titolo)+'</b>'+(r.testo?'<p>'+esc(r.testo)+'</p>':'')+
        (v?'<button type="button" class="lnk2" data-go="'+r.area+'">'+esc(SECN[v.sec].n+' › '+v.t)+'</button>':'')+
        (r.preso_da?'<div class="who">'+avatar(r.preso_da)+'<span><b>'+esc(nome(r.preso_da))+'</b> · entro il '+fmtD(r.entro)+(r.presa_il?'<br><span class="muted small">presa il '+new Date(r.presa_il).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+'</span>':'')+'</span></div>':'')+
        (r.note?'<p class="muted small">Nota: '+esc(r.note)+'</p>':'')+(r.fatta_il?'<p class="muted small">Completata il '+new Date(r.fatta_il).toLocaleDateString('it-IT')+'</p>':'')+'<span class="muted small">Chiesta da '+esc(nome(r.creato_da))+' il '+new Date(r.creato).toLocaleDateString('it-IT')+'</span></article>');
      if(r.allegato&&r.allegato.path)c.appendChild(fileBtn(r.allegato,'Documento allegato'));
      consigliBox(r,c);
      if(r.stato==='aperta'){const b=h('<button type="button" class="bb dark">La prendo io</button>');b.addEventListener('click',()=>takeReq(r.id));c.appendChild(b);}
      if(['presa','lavorazione','attesa'].includes(r.stato)&&(r.preso_da===me||isPres())){const b=h('<div class="seg wrap">'+[['lavorazione','In lavorazione'],['attesa','In attesa'],['fatta','Completata']].map(([k,l])=>'<button type="button" data-s="'+k+'" aria-pressed="'+(r.stato===k)+'">'+l+'</button>').join('')+'</div>');
        b.querySelectorAll('[data-s]').forEach(x=>x.addEventListener('click',()=>sheet(x.textContent,'<div class="ctl"><label for="rs_n">Nota (facoltativa)</label><textarea id="rs_n" placeholder="'+(x.dataset.s==='attesa'?'Per esempio: aspetto il preventivo':'')+'"></textarea></div>','Aggiorna',async(dl)=>{const {error}=await CTX.sb.rpc('aggiorna_richiesta',{rid:r.id,nuovo:x.dataset.s,nota:dl.querySelector('#rs_n').value.trim()});if(error)throw new Error(error.message);await loadSocial();renderReq2();})));c.appendChild(b);}
      if(isPres()){const b=h('<button type="button" class="lnk2 ko">Elimina</button>');b.addEventListener('click',()=>ask('Eliminare la richiesta?','Elimina',async()=>{await CTX.sb.from('richieste').delete().eq('id',r.id);await loadSocial();renderReq2();}));c.appendChild(b);}
      g.appendChild(c);});el.appendChild(g);});
  if(!RICH.length)el.appendChild(h('<div class="card soon"><p>Ancora nessuna richiesta.'+(isPres()?'':' Le richieste le crea il Presidente.')+'</p></div>'));}

/* --- Compiti: area collegata, priorità, allegato, presa in carico con data, riassegnazione, storico --- */
function assegnaCompito(pre){const ppl=Object.values(PEOPLE);pre=pre||{};
  sheet('Assegna un compito','<div class="ctl"><label for="ac_t">Cosa va fatto</label><input type="text" id="ac_t" value="'+esc(pre.titolo||'')+'"></div><div class="ctl"><label for="ac_a">Area e scheda collegata</label>'+areaSelect('ac_a',pre.area||'')+'</div><div class="lab">A chi (puoi sceglierne più di uno)</div><div class="checks">'+ppl.map(p=>'<label><input type="checkbox" value="'+p.id+'"> '+esc(p.nome||p.email)+(p.id===CTX.user.id?' (io)':'')+'</label>').join('')+'</div><div class="when"><div class="ctl"><label for="ac_p">Priorità</label><select id="ac_p">'+PRIORITA.map(p=>'<option>'+p+'</option>').join('')+'</select></div><div class="ctl"><label for="ac_d">Entro (facoltativo)</label><input type="date" id="ac_d" min="'+todayISO()+'"></div></div><label class="ck"><input type="checkbox" id="ac_c"> Chiedi a chi lo riceve di prenderlo in carico indicando la data</label><div class="ctl"><label for="ac_f">Allegato (facoltativo)</label><input type="file" id="ac_f"></div>','Assegna',async(dl)=>{
    const t=dl.querySelector('#ac_t').value.trim();const chi=[...dl.querySelectorAll('.checks input:checked')].map(x=>x.value);if(!t||!chi.length){dl.querySelector('.smsg').textContent='Scrivi cosa va fatto e scegli almeno una persona.';return false;}
    const f=dl.querySelector('#ac_f').files[0];const al=f?await carica(f,'compiti/'+CTX.user.id):null;const chiede=dl.querySelector('#ac_c').checked;
    const rows=chi.map(p=>({per:p,titolo:t,entro:chiede?null:(dl.querySelector('#ac_d').value||null),area:dl.querySelector('#ac_a').value||null,priorita:dl.querySelector('#ac_p').value,allegato:al,chiede_data:chiede,stato:'assegnato',storico:[{quando:new Date().toISOString(),chi:CTX.user.id,cosa:'Assegnato a '+nome(p)}]}));
    const {error}=await CTX.sb.from('compiti').insert(rows);if(error)throw new Error(error.message);await loadSocial();rerender();stEl.textContent='Compito assegnato: '+chi.length+(chi.length===1?' persona riceve':' persone ricevono')+' una notifica.';});}
async function aggiornaCompito(c,campi,cosa){const st=(c.storico||[]).concat([{quando:new Date().toISOString(),chi:CTX.user.id,cosa}]).slice(-30);const {error}=await CTX.sb.from('compiti').update(Object.assign({},campi,{storico:st})).eq('id',c.id);if(error){stEl.textContent=error.message;return;}await loadSocial();rerender();}
function rigaCompito(c,mio){const v=c.area&&VOCE[c.area];const late=!c.fatto&&c.entro&&c.entro<todayISO();
  const row=h('<div class="cmp'+(c.fatto?' done':'')+'"><div class="chips">'+(c.priorita&&c.priorita!=='Normale'?'<span class="chip2 '+(c.priorita==='Urgente'||c.priorita==='Alta'?'ko':'')+'">'+esc(c.priorita)+'</span>':'')+(late?'<span class="chip2 ko">In ritardo</span>':'')+(c.chiede_data&&c.stato==='assegnato'&&!c.fatto?'<span class="chip2">Da prendere in carico</span>':'')+(c.privato?'<span class="chip2">Promemoria</span>':'')+'</div><b>'+esc(c.titolo)+'</b><span class="muted small who2">'+((mio?c.da&&c.da!==CTX.user.id:true)?avatar(mio?c.da:c.per,'xs'):'')+(mio?(c.da&&c.da!==CTX.user.id?'Da '+esc(nome(c.da)):''):'A '+esc(nome(c.per)))+(c.entro?' · entro il '+fmtD(c.entro):'')+(c.fatto?' · fatto':'')+'</span></div>');
  if(v)row.appendChild(h('<button type="button" class="lnk2" data-go="'+c.area+'">Apri '+esc(SECN[v.sec].n+' › '+v.t)+'</button>'));
  if(c.allegato&&c.allegato.path)row.appendChild(fileBtn(c.allegato,'Allegato'));
  const bt=h('<div class="rowb"></div>');
  if(mio&&!c.fatto&&c.chiede_data&&c.stato==='assegnato'){const b=h('<button type="button" class="okb">Lo prendo in carico</button>');b.addEventListener('click',()=>sheet('Entro quando lo fai?','<div class="ctl"><label for="cp_d">Data</label><input type="date" id="cp_d" min="'+todayISO()+'"></div>','Conferma',async(dl)=>{const d=dl.querySelector('#cp_d').value;if(!d){dl.querySelector('.smsg').textContent='Senza data non si può confermare.';return false;}await aggiornaCompito(c,{stato:'preso',entro:d},'Preso in carico entro il '+fmtD(d));}));bt.appendChild(b);}
  else if(mio&&!c.fatto){const b=h('<button type="button" class="okb">Fatto</button>');b.addEventListener('click',()=>aggiornaCompito(c,{fatto:true,stato:'fatto'},'Segnato come fatto'));bt.appendChild(b);}
  if(!mio&&!c.fatto){const b=h('<button type="button">Riassegna</button>');b.addEventListener('click',()=>{const ppl=Object.values(PEOPLE).filter(p=>p.id!==c.per);sheet('Riassegna «'+c.titolo+'»','<div class="ctl"><label for="ra_p">A chi</label><select id="ra_p">'+ppl.map(p=>'<option value="'+p.id+'">'+esc(p.nome||p.email)+'</option>').join('')+'</select></div>','Riassegna',async(dl)=>{const p=dl.querySelector('#ra_p').value;await aggiornaCompito(c,{per:p,stato:'assegnato'},'Riassegnato da '+nome(c.per)+' a '+nome(p));});});bt.appendChild(b);
    const x=h('<button type="button" class="ko">Elimina</button>');x.addEventListener('click',()=>ask('Eliminare il compito?','Elimina',async()=>{await CTX.sb.from('compiti').delete().eq('id',c.id);await loadSocial();rerender();}));bt.appendChild(x);}
  if(bt.children.length)row.appendChild(bt);
  if((c.storico||[]).length){row.appendChild(h('<details class="storico2"><summary>Storico · '+c.storico.length+'</summary>'+c.storico.slice().reverse().map(s=>'<div class="sti">'+esc(s.cosa)+' · <span class="muted">'+esc(nome(s.chi))+', '+new Date(s.quando).toLocaleDateString('it-IT')+'</span></div>').join('')+'</details>'));}
  return row;}
function compitiCard(){const me=CTX.user.id;const mine=COMP.filter(c=>c.per===me),given=COMP.filter(c=>c.da===me&&c.per!==me);const aperti=mine.filter(c=>!c.fatto),fatti=mine.filter(c=>c.fatto);
  const c=h('<section class="card"><div class="wh"><h3>I miei compiti e promemoria</h3><span class="muted">'+fatti.length+' su '+mine.length+' fatti</span></div><div class="clist2"></div><div class="when"><div class="ctl" style="flex:3 1 220px"><label for="pm_t">Nuovo promemoria</label><input type="text" id="pm_t" placeholder="Scrivi qui…"></div><div class="ctl"><label for="pm_d">Entro</label><input type="date" id="pm_d"></div></div><div class="big-btns"><button type="button" class="bb dark" id="pm_ok">Salva promemoria</button><button type="button" class="bb" id="as_ok">Assegna un compito</button></div>'+(given.length?'<h3 style="margin-top:12px">Compiti che hai assegnato</h3><div class="glist"></div>':'')+'</section>');
  const cl=c.querySelector('.clist2');aperti.forEach(x=>cl.appendChild(rigaCompito(x,true)));if(!aperti.length)cl.appendChild(h('<p class="muted">Niente da fare.</p>'));
  if(fatti.length){const d=h('<details class="storico2"><summary>Fatti · '+fatti.length+'</summary></details>');fatti.slice(0,20).forEach(x=>d.appendChild(rigaCompito(x,true)));cl.appendChild(d);}
  const gl=c.querySelector('.glist');if(gl)given.forEach(x=>gl.appendChild(rigaCompito(x,false)));
  c.querySelector('#pm_ok').addEventListener('click',async()=>{const t=c.querySelector('#pm_t').value.trim();if(!t)return;const {error}=await CTX.sb.from('compiti').insert({per:me,titolo:t,entro:c.querySelector('#pm_d').value||null,privato:true});if(error){stEl.textContent=error.message;return;}await loadSocial();rerender();});
  c.querySelector('#as_ok').addEventListener('click',()=>assegnaCompito());return c;}

/* --- Aree personali: private, condivise con persone scelte, visibili a tutti; con documenti --- */
function areeCard(){const me=CTX.user.id;const myA=AREE_P.filter(a=>a.owner===me),oth=AREE_P.filter(a=>a.owner!==me);
  const ac=h('<section class="card"><div class="wh"><h3>Le mie aree</h3><button type="button" class="bb dark sm" id="na">+ Nuova area</button></div><p class="muted">Pagine tue per appunti, liste e documenti. Puoi tenerle private, condividerle con persone scelte o renderle visibili a tutti.'+(CTX.admin?' Come amministratore vedi anche quelle degli altri.':'')+'</p><div class="cgrid"></div></section>');
  const ag=ac.querySelector('.cgrid');
  myA.concat(oth).forEach(a=>{const own=a.owner===me;const cc=(a.condivisa_con||[]);const vis=a.visibile?'<span class="chip2 ok">Visibile a tutti</span>':cc.length?'<span class="chip2">Condivisa con '+esc(cc.map(nome).join(', '))+'</span>':'<span class="chip2">Privata</span>';
    const c=h('<article class="card rc"><div class="chips">'+vis+(own?'':'<span class="chip2">di '+esc(nome(a.owner))+'</span>')+'</div><b class="vn">'+esc(a.titolo)+'</b><p style="white-space:pre-line">'+esc((a.testo||'').slice(0,600))+'</p></article>');
    (a.allegati||[]).forEach(f=>c.appendChild(fileBtn(f)));
    if(own){const b=h('<div class="rowb"><button type="button">Modifica</button><button type="button" class="ko">Elimina</button></div>');b.children[0].addEventListener('click',()=>editArea2(a));b.children[1].addEventListener('click',()=>ask('Eliminare «'+a.titolo+'»?','Elimina',async()=>{await CTX.sb.from('aree_personali').delete().eq('id',a.id);renderMe();}));c.appendChild(b);}
    ag.appendChild(c);});
  ac.querySelector('#na').addEventListener('click',()=>editArea2(null));return ac;}
function editArea2(a){const ppl=Object.values(PEOPLE).filter(p=>p.id!==CTX.user.id);const cc=(a&&a.condivisa_con)||[];const vis=a?(a.visibile?'tutti':cc.length?'scelte':'privata'):'privata';
  const d=sheet(a?'Modifica area':'Nuova area','<div class="ctl"><label for="ap_t">Titolo</label><input type="text" id="ap_t" value="'+esc(a?a.titolo:'')+'"></div><div class="ctl"><label for="ap_x">Contenuto (appunti, liste: una riga per punto)</label><textarea id="ap_x" style="min-height:180px">'+esc(a?a.testo||'':'')+'</textarea></div><div class="lab">Chi la vede</div><div class="seg wrap" id="ap_v">'+[['privata','Solo io'],['scelte','Persone scelte'],['tutti','Tutti']].map(([k,l])=>'<button type="button" data-v="'+k+'" aria-pressed="'+(k===vis)+'">'+l+'</button>').join('')+'</div><div class="checks" id="ap_p"'+(vis==='scelte'?'':' hidden')+'>'+ppl.map(p=>'<label><input type="checkbox" value="'+p.id+'"'+(cc.includes(p.id)?' checked':'')+'> '+esc(p.nome||p.email)+'</label>').join('')+'</div><div class="ctl"><label for="ap_f">Aggiungi un documento</label><input type="file" id="ap_f"></div>','Salva',async(dl)=>{
    const t=dl.querySelector('#ap_t').value.trim();if(!t){dl.querySelector('.smsg').textContent='Scrivi un titolo.';return false;}const v=dl.querySelector('#ap_v [aria-pressed="true"]').dataset.v;
    const f=dl.querySelector('#ap_f').files[0];const al=(a&&a.allegati)||[];const nuovi=f?al.concat([await carica(f,'personali/'+CTX.user.id)]):al;
    const o={titolo:t,testo:dl.querySelector('#ap_x').value,visibile:v==='tutti',condivisa_con:v==='scelte'?[...dl.querySelectorAll('#ap_p input:checked')].map(x=>x.value):[],allegati:nuovi,aggiornato:new Date().toISOString()};
    const q=a?CTX.sb.from('aree_personali').update(o).eq('id',a.id):CTX.sb.from('aree_personali').insert(o);const {error}=await q;if(error)throw new Error(error.message);
    const nuoviC=o.condivisa_con.filter(x=>!cc.includes(x));for(const p of nuoviC)await avvisaUtente(p,nome(CTX.user.id)+' ha condiviso con te l’area «'+t+'»','p-me');renderMe();});
  d.querySelectorAll('#ap_v button').forEach(b=>b.addEventListener('click',()=>{d.querySelectorAll('#ap_v button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));d.querySelector('#ap_p').hidden=b.dataset.v!=='scelte';}));}

/* --- Notifiche: scegli quali ricevere --- */
const CATN=[['p-req','Richieste del Presidente'],['p-me','Compiti, documenti e aree condivise'],['p-home','Inviti alle riunioni'],['percorsi','Percorsi e Sicurezza'],['v-req','Documenti richiesti e arrivati'],['p-pub','Percorsi pubblicati']];
let catDi=n=>['v-psic','v-perc'].includes(n.link)?'percorsi':n.link;
function mutata(n){return !!(PREF.muti&&PREF.muti.includes(catDi(n)));}
function mePrefNoti(el){const muti=PREF.muti||[];const c=h('<section class="card"><h3>Quali notifiche ricevere</h3><p class="muted small">Togli la spunta a quelle che non ti servono: non arrivano né qui né sul telefono.</p><div class="checks">'+CATN.map(([k,l])=>'<label><input type="checkbox" value="'+k+'"'+(muti.includes(k)?'':' checked')+'> '+esc(l)+'</label>').join('')+'</div></section>');
  c.querySelectorAll('input').forEach(i=>i.addEventListener('change',async()=>{PREF.muti=[...c.querySelectorAll('input')].filter(x=>!x.checked).map(x=>x.value);refreshBell();await savePref();stEl.textContent='Preferenze salvate.';}));
  el.insertBefore(c,[...el.children].pop());}

/* --- Calendario unico: eventi, riunioni, sopralluoghi, appuntamenti, percorsi, scadenze --- */
let CALV='mese',CALD=null;const TIPOR=['Riunione','Sopralluogo','Appuntamento'];
const COLC={evento:'#24478F',riunione:'#2A8C6F',sopralluogo:'#D9822B',appuntamento:'#7A4FB5',percorso:'#0B2147',scadenza:'#C0392B'};
function voceCal(){const me=CTX.user.id,out=[];const add=(data,ora,titolo,tipo,go,extra)=>{if(data)out.push(Object.assign({data:String(data).slice(0,10),ora:ora||'',titolo,tipo,go},extra||{}));};
  RIUN.forEach(r=>{const d=new Date(r.quando);const dd=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');add(dd,d.toTimeString().slice(0,5),r.titolo+(r.luogo?' · '+r.luogo:''),(r.tipo||'Riunione').toLowerCase(),'p-cal',{riu:r});});
  vperc().forEach(r=>{if(r.dati.data)add(r.dati.data,r.dati.ora,'Percorso: '+r.dati.nome,'percorso',r.dati.stato==='Pubblicato'?'p-pub':'v-perc');});
  RICH.filter(r=>r.entro&&r.stato!=='fatta'&&(r.preso_da===me||isPres())).forEach(r=>add(r.entro,'','Scade: '+r.titolo,'scadenza','p-req'));
  COMP.filter(c=>c.per===me&&!c.fatto&&c.entro).forEach(c=>add(c.entro,'','Da fare: '+c.titolo,'scadenza','p-me'));
  (VD['v-fatt']||[]).filter(r=>r.dati.tipo!=='Ricavo'&&r.dati.pagata!=='Sì'&&r.dati.scadenza).forEach(r=>add(r.dati.scadenza,'','Fattura da pagare: '+(r.dati.soggetto||''),'scadenza','v-fatt'));
  (VD['v-for27']||[]).forEach(r=>(r.dati.pagamenti||[]).filter(p=>p.data&&statoRata(p)[0]!=='Pagato').forEach(p=>add(p.data,'','Pagamento a '+r.dati.fornitore+' · '+eur(+p.importo||0),'scadenza','v-for27')));
  (VD['v-aut']||[]).filter(r=>r.dati.scadenza).forEach(r=>add(r.dati.scadenza,'','Scade l’autorizzazione: '+r.dati.cosa,'scadenza','v-aut'));
  (VD['v-req']||[]).filter(r=>r.dati.entro&&r.dati.stato!=='Arrivato').forEach(r=>add(r.dati.entro,'','Documento atteso: '+r.dati.documento,'scadenza','v-req'));
  return out.sort((a,b)=>(a.data+a.ora).localeCompare(b.data+b.ora));}
function renderCalU(){const el=document.getElementById('p-cal');el.innerHTML='';const me=CTX.user.id;const base=CALD?new Date(CALD+'T12:00:00'):new Date();const ISO=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  el.appendChild(h('<div class="sh"><span class="eyb">Eventi</span><h2>Calendario organizzativo</h2><p>Riunioni, sopralluoghi, appuntamenti con i fornitori, percorsi e scadenze. Le riunioni le vedono solo gli invitati. Gli eventi della festa sono nel Calendario eventi ufficiali.</p></div>'));
  const bar=h('<div class="calbar"><div class="seg">'+[['giorno','Giorno'],['settimana','Settimana'],['mese','Mese']].map(([k,l])=>'<button type="button" data-v="'+k+'" aria-pressed="'+(k===CALV)+'">'+l+'</button>').join('')+'</div><div class="calnav"><button type="button" data-n="-1" aria-label="Indietro">‹</button><button type="button" data-n="0">Oggi</button><button type="button" data-n="1" aria-label="Avanti">›</button></div></div>');
  bar.querySelectorAll('[data-v]').forEach(b=>b.addEventListener('click',()=>{CALV=b.dataset.v;renderCalU();}));
  bar.querySelectorAll('[data-n]').forEach(b=>b.addEventListener('click',()=>{const n=+b.dataset.n;if(!n){CALD=null;}else{const d=new Date(base);if(CALV==='mese')d.setMonth(d.getMonth()+n,1);else d.setDate(d.getDate()+n*(CALV==='settimana'?7:1));CALD=ISO(d);}renderCalU();}));
  el.appendChild(bar);
  el.appendChild(addBtn('+ Nuova riunione, sopralluogo o appuntamento',nuovaRiunione));
  const items=voceCal();const byD={};items.forEach(x=>(byD[x.data]=byD[x.data]||[]).push(x));
  const voce=x=>{const b=h('<button type="button" class="calit" style="--c:'+COLC[x.tipo]+'"><i></i><span><b>'+(x.ora?esc(x.ora)+' ':'')+esc(x.titolo)+'</b><em>'+esc(x.tipo)+'</em></span></button>');b.addEventListener('click',()=>{if(x.riu)return schedaRiunione(x.riu);if(x.ev)return schedaEvento(x.ev);go(x.go);});return b;};
  const tit=h('<h3 class="gh"></h3>');el.appendChild(tit);
  if(CALV==='mese'){tit.textContent=base.toLocaleDateString('it-IT',{month:'long',year:'numeric'});const f=new Date(base.getFullYear(),base.getMonth(),1);const start=new Date(f);start.setDate(1-((f.getDay()+6)%7));
    const g=h('<div class="calm">'+['lun','mar','mer','gio','ven','sab','dom'].map(d=>'<span class="calh">'+d+'</span>').join('')+'</div>');
    for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const k=ISO(d);const L1=byD[k]||[];const cell=h('<button type="button" class="calc'+(d.getMonth()!==base.getMonth()?' fuori':'')+(k===todayISO()?' oggi':'')+'"><b>'+d.getDate()+'</b><span class="dots">'+L1.slice(0,4).map(x=>'<i style="background:'+COLC[x.tipo]+'"></i>').join('')+(L1.length>4?'+':'')+'</span></button>');cell.addEventListener('click',()=>{CALD=k;CALV='giorno';renderCalU();});g.appendChild(cell);}
    el.appendChild(g);const mm=items.filter(x=>x.data.slice(0,7)===ISO(base).slice(0,7));const lst=h('<section class="card"></section>');mm.forEach(x=>{lst.appendChild(h('<span class="muted small">'+fmtD(x.data)+'</span>'));lst.appendChild(voce(x));});if(!mm.length)lst.appendChild(h('<p class="muted">Niente in questo mese.</p>'));el.appendChild(lst);}
  else{const days=CALV==='giorno'?1:7;const s0=new Date(base);if(CALV==='settimana')s0.setDate(s0.getDate()-((s0.getDay()+6)%7));
    tit.textContent=CALV==='giorno'?s0.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):'Settimana dal '+s0.toLocaleDateString('it-IT',{day:'numeric',month:'long'});
    for(let i=0;i<days;i++){const d=new Date(s0);d.setDate(s0.getDate()+i);const k=ISO(d);const L1=byD[k]||[];const c=h('<section class="card calday'+(k===todayISO()?' oggi':'')+'"><b class="cdh">'+d.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'})+'</b></section>');L1.forEach(x=>c.appendChild(voce(x)));if(!L1.length)c.appendChild(h('<p class="muted small">Niente in programma.</p>'));el.appendChild(c);}}
  el.appendChild(h('<div class="legend">'+Object.entries(COLC).map(([k,c])=>'<span><i style="background:'+c+'"></i>'+k+'</span>').join('')+'</div>'));}
function nuovaRiunione(){const me=CTX.user.id;const ppl=Object.values(PEOPLE).filter(p=>p.id!==me);
  sheet('Nuovo appuntamento','<div class="ctl"><label for="ri_k">Tipo</label><select id="ri_k">'+TIPOR.map(t=>'<option>'+t+'</option>').join('')+'</select></div><div class="ctl"><label for="ri_t">Oggetto</label><input type="text" id="ri_t" placeholder="Riunione del direttivo"></div><div class="when"><div class="ctl"><label for="ri_d">Giorno</label><input type="date" id="ri_d" min="'+todayISO()+'"></div><div class="ctl"><label for="ri_o">Ora</label><input type="time" id="ri_o" value="18:30"></div></div><div class="ctl"><label for="ri_l">Luogo</label><input type="text" id="ri_l"></div><div class="lab">Chi inviti (lo vedono solo gli invitati)</div><div class="checks">'+ppl.map(p=>'<label><input type="checkbox" value="'+p.id+'"> '+esc(p.nome||p.email)+'</label>').join('')+'</div><div class="ctl"><label for="ri_f">Documento (ordine del giorno…)</label><input type="file" id="ri_f"></div>','Crea e invita',async(dl)=>{
    const t=dl.querySelector('#ri_t').value.trim(),d=dl.querySelector('#ri_d').value,o=dl.querySelector('#ri_o').value||'18:00';if(!t||!d){dl.querySelector('.smsg').textContent='Scrivi oggetto e giorno.';return false;}
    const f=dl.querySelector('#ri_f').files[0];const al=f?[await carica(f,'riunioni/'+me)]:[];
    const {data,error}=await CTX.sb.from('riunioni').insert({titolo:t,tipo:dl.querySelector('#ri_k').value,quando:new Date(d+'T'+o).toISOString(),luogo:dl.querySelector('#ri_l').value.trim()||null,allegati:al}).select().single();if(error)throw new Error(error.message);
    const inv=[...dl.querySelectorAll('.checks input:checked')].map(x=>({riunione_id:data.id,user_id:x.value}));if(inv.length){const r2=await CTX.sb.from('inviti_riunione').insert(inv);if(r2.error)throw new Error(r2.error.message);}
    await loadSocial();renderCalU();stEl.textContent='Creato. Gli invitati ricevono una notifica.';});}
function schedaRiunione(r){const me=CTX.user.id;const my=INVM.find(i=>i.riunione_id===r.id&&i.user_id===me);const inv=INVM.filter(i=>i.riunione_id===r.id);
  const d=sheet((r.tipo||'Riunione')+': '+r.titolo,'<div class="fact2"><span>Quando</span><b>'+new Date(r.quando).toLocaleString('it-IT',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})+'</b></div>'+(r.luogo?'<div class="fact2"><span>Dove</span><b>'+esc(r.luogo)+'</b></div>':'')+'<div class="fact2"><span>Organizza</span><b>'+esc(nome(r.creato_da))+'</b></div><div class="chips">'+inv.map(i=>'<span class="chip2 chipav '+(i.stato==='accetta'?'ok':i.stato==='rifiuta'?'ko':'')+'">'+avatar(i.user_id,'xs')+esc(nome(i.user_id))+'</span>').join('')+'</div><div class="ral"></div>'+(my&&my.stato==='invitato'?'<div class="rowb"><button type="button" class="okb" data-r="accetta">Ci sarò</button><button type="button" class="ko" data-r="rifiuta">Non posso</button></div>':'')+(r.creato_da===me?'<button type="button" class="lnk2 ko" id="rdel">Annulla</button>':''),'Chiudi',async()=>{});
  (r.allegati||[]).forEach(f=>d.querySelector('.ral').appendChild(fileBtn(f)));
  d.querySelectorAll('[data-r]').forEach(b=>b.addEventListener('click',async()=>{await answer(r.id,b.dataset.r);d.remove();renderCalU();}));
  const x=d.querySelector('#rdel');if(x)x.addEventListener('click',()=>{d.remove();ask('Annullare «'+r.titolo+'»?','Annulla',async()=>{await CTX.sb.from('riunioni').delete().eq('id',r.id);await loadSocial();renderCalU();});});}

/* --- Scheda evento completa (si apre dal calendario) --- */
const EVSTATI=['Idea','In preparazione','Confermato','Fatto','Annullato'];
function schedaEvento(e){const L1=VD['s-ev']||[];const r=L1.find(x=>x.dati.evid===String(e.id));const d=r?r.dati:{evid:String(e.id)};const can=CTX.canEdit('s-ev');const ppl=Object.values(PEOPLE);
  const perc=vperc();const att=(d.attivita||[]).map(a=>a.cosa+(a.chi?' — '+nome(a.chi):'')).join('\n');
  const body='<p class="muted">'+esc(e.luogo||'')+(e.ora?' · ore '+esc(e.ora):'')+'</p><div class="ctl"><label for="sx_d">Descrizione</label><textarea id="sx_d">'+esc(d.descr||e.desc||'')+'</textarea></div><div class="when"><div class="ctl"><label for="sx_r">Responsabile</label><select id="sx_r"><option value="">Nessuno</option>'+ppl.map(p=>'<option value="'+p.id+'"'+(p.id===d.resp?' selected':'')+'>'+esc(p.nome||p.email)+'</option>').join('')+'</select></div><div class="ctl"><label for="sx_s">Stato</label><select id="sx_s">'+EVSTATI.map(s=>'<option'+(s===(d.stato||'Idea')?' selected':'')+'>'+s+'</option>').join('')+'</select></div></div>'+
    '<div class="ctl"><label for="sx_pa">Partecipanti e invitati</label><textarea id="sx_pa">'+esc(d.partecipanti||'')+'</textarea></div><div class="ctl"><label for="sx_pr">Programma</label><textarea id="sx_pr">'+esc(d.programma||'')+'</textarea></div><div class="when"><div class="ctl"><label for="sx_c">Costi stimati (€)</label><input type="number" id="sx_c" value="'+esc(d.costi||e.costo||'')+'"></div><div class="ctl"><label for="sx_ri">Ricavi stimati (€)</label><input type="number" id="sx_ri" value="'+esc(d.ricavi||'')+'"></div></div>'+
    '<div class="ctl"><label for="sx_pe">Percorso collegato</label><select id="sx_pe"><option value="">Nessuno</option>'+perc.map(p=>'<option value="'+p.id+'"'+(p.id===d.percorso?' selected':'')+'>'+esc(p.dati.nome)+'</option>').join('')+'</select></div><div class="ctl"><label for="sx_at">Chi fa cosa (una riga per attività: «cosa — persona»)</label><textarea id="sx_at">'+esc(att)+'</textarea></div><div class="ral"></div>'+(can?'<div class="ctl"><label for="sx_f">Aggiungi un documento</label><input type="file" id="sx_f"></div><button type="button" class="lnk2" id="sx_fo">Cosa serve per questo evento? Trova i fornitori</button>':'');
  const dl=sheet('Scheda: '+e.n,body,can?'Salva':'Chiudi',async(x)=>{if(!can)return;const f=x.querySelector('#sx_f').files[0];const files=(d.files||[]).concat(f?[await carica(f,'s-ev')]:[]);
    const att2=x.querySelector('#sx_at').value.split('\n').map(s=>s.trim()).filter(Boolean).map(s=>{const [cosa,chiN]=s.split(/\s+—\s+|\s+-\s+/);const p=chiN&&ppl.find(q=>(q.nome||q.email).toLowerCase()===chiN.trim().toLowerCase());return {cosa,chi:p?p.id:'',chiTesto:chiN||''};});
    const o=Object.assign({},d,{nome:e.n,descr:x.querySelector('#sx_d').value.trim(),resp:x.querySelector('#sx_r').value,stato:x.querySelector('#sx_s').value,partecipanti:x.querySelector('#sx_pa').value.trim(),programma:x.querySelector('#sx_pr').value.trim(),costi:x.querySelector('#sx_c').value,ricavi:x.querySelector('#sx_ri').value,percorso:x.querySelector('#sx_pe').value,attivita:att2,files});
    if(o.resp&&o.resp!==d.resp&&o.resp!==CTX.user.id)avvisaUtente(o.resp,'Sei responsabile dell’evento «'+e.n+'»','p-cal');
    for(const a of att2)if(a.chi&&a.chi!==CTX.user.id&&!(d.attivita||[]).some(b=>b.chi===a.chi&&b.cosa===a.cosa))await CTX.sb.from('compiti').insert({per:a.chi,titolo:a.cosa+' (evento «'+e.n+'»)',area:'s-ev'});
    const q=r?CTX.sb.from('voci_dati').update({dati:o,aggiornato:new Date().toISOString()}).eq('id',r.id):CTX.sb.from('voci_dati').insert({voce:'s-ev',dati:o});const {error}=await q;if(error)throw new Error(error.message);await Promise.all([loadVD(),loadSocial()]);stEl.textContent='Scheda salvata.';});
  (d.files||[]).forEach(f=>dl.querySelector('.ral').appendChild(fileBtn(f)));
  if((d.fornitori||[]).length)dl.querySelector('.ral').appendChild(h('<div><div class="lab">Fornitori per questo evento</div>'+d.fornitori.map(f=>'<div class="rq"><div><b>'+esc(f.servizio)+' · '+esc(f.fornitore||'fornitore da trovare')+'</b><span>'+esc([f.quantita,f.data?fmtD(f.data):'',f.importo?eur(+f.importo):'',f.stato,f.resp?'segue '+nome(f.resp):''].filter(Boolean).join(' · '))+'</span></div></div>').join('')+'</div>'));if(!can)dl.querySelectorAll('input,textarea,select').forEach(i=>i.disabled=true);
  const fo=dl.querySelector('#sx_fo');if(fo)fo.addEventListener('click',()=>{dl.remove();chiediFornEvento(e);});}
const _extraVD=extraVD;extraVD=function(){return _extraVD().concat(canV('s-ev')?['s-ev']:[]);};

/* --- ricerca anche nei dati nuovi --- */
function extraIDX(IDX){Object.entries(VD).forEach(([k,L1])=>{const v=VOCE[k];if(!v)return;(L1||[]).forEach(r=>{const d=r.dati||{};const t=d.nome||d.soggetto||d.fornitore||d.oggetto||d.cosa||d.documento||d.voce||d.beneficiario||d.spazio||'';if(!t)return;IDX.push({k:v.t,n:t,s:[d.stato,d.tipo,d.regione,d.data].filter(Boolean).join(' · '),go:()=>go(k)});});});
  RICH.forEach(r=>IDX.push({k:'Richiesta del Presidente',n:r.titolo,s:(STR[r.stato]||STR.aperta)[0],go:()=>go('p-req')}));
  COMP.filter(c=>c.per===CTX.user.id).forEach(c=>IDX.push({k:'Compito',n:c.titolo,s:c.entro?'entro il '+fmtD(c.entro):'',go:()=>go('p-me')}));
  RIUN.forEach(r=>IDX.push({k:r.tipo||'Riunione',n:r.titolo,s:new Date(r.quando).toLocaleDateString('it-IT'),go:()=>go('p-cal')}));}
